create extension if not exists pgcrypto;
create type public.user_role as enum ('employee','hc_admin');
create type public.leave_type as enum ('sick','leave','permission');
create type public.leave_status as enum ('pending','approved','rejected');
create type public.slot_status as enum ('on_time','late','early_out','absent');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,role public.user_role not null default 'employee',department text,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.company_locations(id uuid default gen_random_uuid() primary key,name text not null,latitude double precision not null,longitude double precision not null,radius_meters int not null default 50 check(radius_meters>0),is_active boolean default true,created_at timestamptz default now());
create table public.attendances(id uuid default gen_random_uuid() primary key,user_id uuid not null references public.profiles(id) on delete cascade,date date not null default current_date,slot_1_time timestamptz,slot_1_photo_url text,slot_1_lat double precision,slot_1_lng double precision,slot_1_status public.slot_status,slot_2_time timestamptz,slot_2_photo_url text,slot_2_lat double precision,slot_2_lng double precision,slot_2_status public.slot_status,slot_3_time timestamptz,slot_3_photo_url text,slot_3_lat double precision,slot_3_lng double precision,slot_3_status public.slot_status,slot_4_time timestamptz,slot_4_photo_url text,slot_4_lat double precision,slot_4_lng double precision,slot_4_status public.slot_status,created_at timestamptz default now(),updated_at timestamptz default now(),unique(user_id,date));
create table public.leave_requests(id uuid default gen_random_uuid() primary key,user_id uuid not null references public.profiles(id) on delete cascade,type public.leave_type not null,start_date date not null,end_date date not null check(end_date>=start_date),reason text not null,attachment_url text,status public.leave_status default 'pending',approved_by uuid references public.profiles(id),rejection_note text,created_at timestamptz default now());
create or replace function public.is_hc_admin() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.profiles where id=auth.uid() and role='hc_admin')$$;
alter table public.profiles enable row level security;alter table public.company_locations enable row level security;alter table public.attendances enable row level security;alter table public.leave_requests enable row level security;
create policy "profiles_self_read" on public.profiles for select using(id=auth.uid() or public.is_hc_admin());
create policy "admins_manage_profiles" on public.profiles for all using(public.is_hc_admin()) with check(public.is_hc_admin());
create policy "locations_authenticated_read" on public.company_locations for select to authenticated using(true);
create policy "admins_manage_locations" on public.company_locations for all using(public.is_hc_admin()) with check(public.is_hc_admin());
create policy "employees_read_own_attendance" on public.attendances for select using(user_id=auth.uid() or public.is_hc_admin());
create policy "employees_insert_own_attendance" on public.attendances for insert with check(user_id=auth.uid() or public.is_hc_admin());
create policy "employees_update_own_attendance" on public.attendances for update using(user_id=auth.uid() or public.is_hc_admin()) with check(user_id=auth.uid() or public.is_hc_admin());
create policy "employees_read_own_leave" on public.leave_requests for select using(user_id=auth.uid() or public.is_hc_admin());
create policy "employees_create_own_leave" on public.leave_requests for insert with check(user_id=auth.uid() and status='pending');
create policy "admins_manage_leave" on public.leave_requests for update using(public.is_hc_admin()) with check(public.is_hc_admin());
